mapper.select:
SELECT id, tenant_code, doc_no, category_id, title, summary, source_type, file_id, status, hit_count, useful_rate, author, publish_time, chunk_count, index_status, index_message, file_name, file_size, create_time, update_time, creator, editor, is_deleted FROM kb_document WHERE tenant_code = #{tenantCode} AND is_deleted = FALSE
AND category_id = #{categoryId}
AND status = #{status}
AND (doc_no ILIKE '%' || #{keyword} || '%' OR title ILIKE '%' || #{keyword} || '%' OR summary ILIKE '%' || #{keyword} || '%' OR file_name ILIKE '%' || #{keyword} || '%')
ORDER BY update_time DESC, id DESC LIMIT #{limit}
